11	// Author: Gu, Zihan
12	// Description:
13	`timescale 1ns/1ns
14	`include "define.v"
15	
16	module tc_mul_pipe #(
17	  parameter EXPWIDTH  = 8,
18	  parameter PRECISION = 24,
19	  parameter LATENCY   = 2
20	)(
21	  input                                 clk               ,
22	  input                                 rst_n             ,
23	
24	  //input   [2:0]                         op_i              ,
25	  input   [EXPWIDTH+PRECISION-1:0]      a_i               ,
26	  input   [EXPWIDTH+PRECISION-1:0]      b_i               ,
27	  //input   [EXPWIDTH+PRECISION-1:0]      c_i               ,
28	  input   [2:0]                         rm_i              ,
29	  input   [EXPWIDTH+PRECISION-1:0]      ctrl_c_i          ,
30	  input   [2:0]                         ctrl_rm_i         ,
31	  input   [7:0]                         ctrl_reg_idxw_i   ,
32	  input   [`DEPTH_WARP-1:0]             ctrl_warpid_i     ,
33	
34	  input                                 in_valid_i        ,
35	  input                                 out_ready_i       ,
36	
37	  output                                in_ready_o        ,
38	  output                                out_valid_o       ,
39	
40	  output  [EXPWIDTH+PRECISION-1:0]      result_o          ,
41	  output  [4:0]                         fflags_o          ,
42	  output  [EXPWIDTH+PRECISION-1:0]      ctrl_c_o          ,
43	  output  [2:0]                         ctrl_rm_o         ,
44	  output  [7:0]                         ctrl_reg_idxw_o   ,
45	  output  [`DEPTH_WARP-1:0]             ctrl_warpid_o     
46	);
47	
48	  //ctrl reg
49	  reg  [EXPWIDTH+PRECISION-1:0]ctrl_c_reg1          ;
50	  reg  [2:0]                   ctrl_rm_reg1         ;
51	  reg  [7:0]                   ctrl_reg_idxw_reg1   ;
52	  reg  [`DEPTH_WARP-1:0]       ctrl_warpid_reg1     ;
53	  reg  [EXPWIDTH+PRECISION-1:0]ctrl_c_reg2          ;
54	  reg  [2:0]                   ctrl_rm_reg2         ;
55	  reg  [7:0]                   ctrl_reg_idxw_reg2   ;
56	  reg  [`DEPTH_WARP-1:0]       ctrl_warpid_reg2     ;
57	  //for pipeline reg valid: latency = 2
58	  reg                           in_valid_reg1;
59	  reg                           in_valid_reg2;
60	  wire                          reg_en1      ;
61	  wire                          reg_en2      ;
62	  //s1 output
63	  wire                          s1_out_special_case_valid      ; 
64	  wire                          s1_out_special_case_nan        ;
65	  wire                          s1_out_special_case_inf        ;
66	  wire                          s1_out_special_case_inv        ;
67	  wire                          s1_out_special_case_haszero    ;
68	  wire                          s1_out_earyl_overflow          ;
69	  wire                          s1_out_prod_sign               ;
70	  wire [EXPWIDTH:0]             s1_out_shift_amt               ;
71	  wire [EXPWIDTH:0]             s1_out_exp_shifted             ;
72	  wire                          s1_out_may_be_subnormal        ;
73	  wire [2:0]                    s1_out_rm                      ;
74	  //s1 output reg
75	  reg                           s1_out_special_case_valid_reg  ; 
76	  reg                           s1_out_special_case_nan_reg    ;
77	  reg                           s1_out_special_case_inf_reg    ;
78	  reg                           s1_out_special_case_inv_reg    ;
79	  reg                           s1_out_special_case_haszero_reg;
80	  reg                           s1_out_earyl_overflow_reg      ;
81	  reg                           s1_out_prod_sign_reg           ;
82	  reg  [EXPWIDTH:0]             s1_out_shift_amt_reg           ;
83	  reg  [EXPWIDTH:0]             s1_out_exp_shifted_reg         ;
84	  reg                           s1_out_may_be_subnormal_reg    ;
85	  reg  [2:0]                    s1_out_rm_reg                  ;
86	  //naivemultiplier
87	  wire                          a_exp_is_zero                  ;
88	  wire                          b_exp_is_zero                  ;
89	  //wire                          raw_a_sign                     ;
90	  //wire                          raw_b_sign                     ;
91	  //wire [EXPWIDTH-1:0]           raw_a_exp                      ;
92	  //wire [EXPWIDTH-1:0]           raw_b_exp                      ;
93	  wire [PRECISION-1:0]          raw_a_sig                      ;
94	  wire [PRECISION-1:0]          raw_b_sig                      ;
95	  wire [2*PRECISION-1:0]        naivemultiplier_result         ;
96	  //s2 output
97	  wire                          s2_out_special_case_valid      ;
98	  wire                          s2_out_special_case_nan        ;
99	  wire                          s2_out_special_case_inf        ;
100	  wire                          s2_out_special_case_inv        ;
101	  wire                          s2_out_special_case_haszero    ;
102	  wire                          s2_out_earyl_overflow          ;
103	  wire [PRECISION*2-1:0]        s2_out_prod                    ;
104	  wire                          s2_out_prod_sign               ;
105	  wire [EXPWIDTH:0]             s2_out_shift_amt               ;
106	  wire [EXPWIDTH:0]             s2_out_exp_shifted             ;
107	  wire                          s2_out_may_be_subnormal        ;
108	  wire [2:0]                    s2_out_rm                      ;
109	  //s2 output reg
110	  reg                           s2_out_special_case_valid_reg  ;
111	  reg                           s2_out_special_case_nan_reg    ;
112	  reg                           s2_out_special_case_inf_reg    ;
113	  reg                           s2_out_special_case_inv_reg    ;
114	  reg                           s2_out_special_case_haszero_reg;
115	  reg                           s2_out_earyl_overflow_reg      ;
116	  reg  [PRECISION*2-1:0]        s2_out_prod_reg                ;
117	  reg                           s2_out_prod_sign_reg           ;
118	  reg  [EXPWIDTH:0]             s2_out_shift_amt_reg           ;
119	  reg  [EXPWIDTH:0]             s2_out_exp_shifted_reg         ;
120	  reg                           s2_out_may_be_subnormal_reg    ;
121	  reg  [2:0]                    s2_out_rm_reg                  ;
122	
123	  wire                          s3_out_to_fadd_fp_prod_sign    ; 
124	  wire [EXPWIDTH-1:0]           s3_out_to_fadd_fp_prod_exp     ; 
125	  wire [2*PRECISION-2:0]        s3_out_to_fadd_fp_prod_sig     ; 
126	  wire                          s3_out_to_fadd_is_nan          ; 
127	  wire                          s3_out_to_fadd_is_inf          ; 
128	  wire                          s3_out_to_fadd_is_inv          ; 
129	  wire                          s3_out_to_fadd_overflow        ;  
130	
131	
132	  always@(posedge clk or negedge rst_n) begin
133	    if(!rst_n) begin
134	      in_valid_reg1 <= 'd0 ;
135	      in_valid_reg2 <= 'd0 ;
136	    end
137	    else begin
138	      if(!(!out_ready_i && in_valid_reg1 && in_valid_reg2)) begin
139	        in_valid_reg1 <= in_valid_i   ;
140	      end
141	      else begin
142	        in_valid_reg1 <= in_valid_reg1;
143	      end
144	      if(!(!out_ready_i && in_valid_reg2)) begin        
145	        in_valid_reg2 <= in_valid_reg1;
146	      end
147	      else begin
148	        in_valid_reg2 <= in_valid_reg2;
149	      end
150	    end
151	  end
152	
153	  assign reg_en1 = in_valid_i && !(in_valid_reg1 && in_valid_reg2 && !out_ready_i) ;
154	  assign reg_en2 = in_valid_reg1 && !(in_valid_reg2 && !out_ready_i)               ;
155	
156	  //for valid and ready
157	  assign in_ready_o  = !(!out_ready_i && in_valid_reg1 && in_valid_reg2) ;
158	  assign out_valid_o = in_valid_reg2                                     ;
159	
160	  //例化fmul_s1
161	  fmul_s1 #(
162	    .EXPWIDTH  (EXPWIDTH ),
163	    .PRECISION (PRECISION)
164	  )
165	  U_fmul_s1 (
166	    .a_i                       (a_i                        ), 
167	    .b_i                       (b_i                        ),
168	    .rm_i                      (rm_i                       ),
169	    .out_special_case_valid_o  (s1_out_special_case_valid  ),
170	    .out_special_case_nan_o    (s1_out_special_case_nan    ),
171	    .out_special_case_inf_o    (s1_out_special_case_inf    ),
172	    .out_special_case_inv_o    (s1_out_special_case_inv    ),
173	    .out_special_case_haszero_o(s1_out_special_case_haszero),
174	    .out_earyl_overflow_o      (s1_out_earyl_overflow      ),
175	    .out_prod_sign_o           (s1_out_prod_sign           ),
176	    .out_shift_amt_o           (s1_out_shift_amt           ),
177	    .out_exp_shifted_o         (s1_out_exp_shifted         ),
178	    .out_may_be_subnormal_o    (s1_out_may_be_subnormal    ),
179	    .out_rm_o                  (s1_out_rm                  )
180	  );
181	
182	  //寄存s1的输出
183	  always@(posedge clk or negedge rst_n) begin
184	    if(!rst_n) begin
185	      s1_out_special_case_valid_reg   <= 'd0;   
186	      s1_out_special_case_nan_reg     <= 'd0;
187	      s1_out_special_case_inf_reg     <= 'd0;
188	      s1_out_special_case_inv_reg     <= 'd0;
189	      s1_out_special_case_haszero_reg <= 'd0;
190	      s1_out_earyl_overflow_reg       <= 'd0;
191	      s1_out_prod_sign_reg            <= 'd0;
192	      s1_out_shift_amt_reg            <= 'd0;
193	      s1_out_exp_shifted_reg          <= 'd0;
194	      s1_out_may_be_subnormal_reg     <= 'd0;
195	      s1_out_rm_reg                   <= 'd0;
196	      ctrl_c_reg1                     <= 'd0;
197	      ctrl_rm_reg1                    <= 'd0;
198	      ctrl_reg_idxw_reg1              <= 'd0;
199	      ctrl_warpid_reg1                <= 'd0;
200	    end
201	    else if(reg_en1) begin
202	      s1_out_special_case_valid_reg   <= s1_out_special_case_valid  ;  
203	      s1_out_special_case_nan_reg     <= s1_out_special_case_nan    ;
204	      s1_out_special_case_inf_reg     <= s1_out_special_case_inf    ;
205	      s1_out_special_case_inv_reg     <= s1_out_special_case_inv    ;
206	      s1_out_special_case_haszero_reg <= s1_out_special_case_haszero;
207	      s1_out_earyl_overflow_reg       <= s1_out_earyl_overflow      ;
208	      s1_out_prod_sign_reg            <= s1_out_prod_sign           ;
209	      s1_out_shift_amt_reg            <= s1_out_shift_amt           ;
210	      s1_out_exp_shifted_reg          <= s1_out_exp_shifted         ;
211	      s1_out_may_be_subnormal_reg     <= s1_out_may_be_subnormal    ;
212	      s1_out_rm_reg                   <= s1_out_rm                  ;
213	      ctrl_c_reg1                     <= ctrl_c_i                   ; 
214	      ctrl_rm_reg1                    <= ctrl_rm_i                  ;
215	      ctrl_reg_idxw_reg1              <= ctrl_reg_idxw_i            ;
216	      ctrl_warpid_reg1                <= ctrl_warpid_i              ;
217	    end
218	    else begin
219	      s1_out_special_case_valid_reg   <= s1_out_special_case_valid_reg  ;   
220	      s1_out_special_case_nan_reg     <= s1_out_special_case_nan_reg    ;
221	      s1_out_special_case_inf_reg     <= s1_out_special_case_inf_reg    ;
222	      s1_out_special_case_inv_reg     <= s1_out_special_case_inv_reg    ;
223	      s1_out_special_case_haszero_reg <= s1_out_special_case_haszero_reg;
224	      s1_out_earyl_overflow_reg       <= s1_out_earyl_overflow_reg      ;
225	      s1_out_prod_sign_reg            <= s1_out_prod_sign_reg           ;
226	      s1_out_shift_amt_reg            <= s1_out_shift_amt_reg           ;
227	      s1_out_exp_shifted_reg          <= s1_out_exp_shifted_reg         ;
228	      s1_out_may_be_subnormal_reg     <= s1_out_may_be_subnormal_reg    ;
229	      s1_out_rm_reg                   <= s1_out_rm_reg                  ;
230	      ctrl_c_reg1                     <= ctrl_c_reg1                    ;
231	      ctrl_rm_reg1                    <= ctrl_rm_reg1                   ;
232	      ctrl_reg_idxw_reg1              <= ctrl_reg_idxw_reg1             ;
233	      ctrl_warpid_reg1                <= ctrl_warpid_reg1               ;
234	    end
235	  end
236	
237	  //例化naivemultiplier
238	  assign a_exp_is_zero   = a_i[EXPWIDTH+PRECISION-2:PRECISION-1] == 'd0                                ;
239	  assign b_exp_is_zero   = b_i[EXPWIDTH+PRECISION-2:PRECISION-1] == 'd0                                ;
240	  //assign raw_a_sign      = a_i[EXPWIDTH+PRECISION-1]                                                   ;
241	  //assign raw_b_sign      = b_i[EXPWIDTH+PRECISION-1]                                                   ;
242	  //assign raw_a_exp       = a_i[EXPWIDTH+PRECISION-2:PRECISION-1] | {{(EXPWIDTH-1){1'b0}},a_exp_is_zero};
243	  //assign raw_b_exp       = b_i[EXPWIDTH+PRECISION-2:PRECISION-1] | {{(EXPWIDTH-1){1'b0}},b_exp_is_zero};
244	  assign raw_a_sig       = {!a_exp_is_zero,a_i[PRECISION-2:0]}                                         ;
245	  assign raw_b_sig       = {!b_exp_is_zero,b_i[PRECISION-2:0]}                                         ; 
246	  naivemultiplier #(
247	    .LEN(PRECISION)
248	  )
249	  U_naivemultiplier (
250	    .clk      (clk                   ),
251	    .rst_n    (rst_n                 ),
252	    .regenable(reg_en1               ),
253	    .a        (raw_a_sig             ),
254	    .b        (raw_b_sig             ),
255	    .result   (naivemultiplier_result)
256	  );
257	
258	  //例化fmul_s2
259	  fmul_s2 #(
260	    .EXPWIDTH (EXPWIDTH ),
261	    .PRECISION(PRECISION)
262	  )
263	  U_fmul_s2 (
264	    .in_special_case_valid_i   (s1_out_special_case_valid_reg  ),  
265	    .in_special_case_nan_i     (s1_out_special_case_nan_reg    ),
266	    .in_special_case_inf_i     (s1_out_special_case_inf_reg    ),
267	    .in_special_case_inv_i     (s1_out_special_case_inv_reg    ),
268	    .in_special_case_haszero_i (s1_out_special_case_haszero_reg),
269	    .in_earyl_overflow_i       (s1_out_earyl_overflow_reg      ),
270	    .in_prod_sign_i            (s1_out_prod_sign_reg           ),
271	    .in_shift_amt_i            (s1_out_shift_amt_reg           ),
272	    .in_exp_shifted_i          (s1_out_exp_shifted_reg         ),
273	    .in_may_be_subnormal_i     (s1_out_may_be_subnormal_reg    ),
274	    .in_rm_i                   (s1_out_rm_reg                  ),
275	    .prod_i                    (naivemultiplier_result         ),
276	    .out_special_case_valid_o  (s2_out_special_case_valid      ),   
277	    .out_special_case_nan_o    (s2_out_special_case_nan        ),  
278	    .out_special_case_inf_o    (s2_out_special_case_inf        ),  
279	    .out_special_case_inv_o    (s2_out_special_case_inv        ),  
280	    .out_special_case_haszero_o(s2_out_special_case_haszero    ),  
281	    .out_earyl_overflow_o      (s2_out_earyl_overflow          ),  
282	    .out_prod_o                (s2_out_prod                    ),  
283	    .out_prod_sign_o           (s2_out_prod_sign               ),  
284	    .out_shift_amt_o           (s2_out_shift_amt               ),  
285	    .out_exp_shifted_o         (s2_out_exp_shifted             ),  
286	    .out_may_be_subnormal_o    (s2_out_may_be_subnormal        ),  
287	    .out_rm_o                  (s2_out_rm                      )
288	  );
289	
290	  //寄存s2的输出
291	  always@(posedge clk or negedge rst_n) begin
292	    if(!rst_n) begin
293	      s2_out_special_case_valid_reg   <= 'd0;    
294	      s2_out_special_case_nan_reg     <= 'd0;
295	      s2_out_special_case_inf_reg     <= 'd0;
296	      s2_out_special_case_inv_reg     <= 'd0;
297	      s2_out_special_case_haszero_reg <= 'd0;
298	      s2_out_earyl_overflow_reg       <= 'd0; 
299	      s2_out_prod_reg                 <= 'd0;
300	      s2_out_prod_sign_reg            <= 'd0;
301	      s2_out_shift_amt_reg            <= 'd0;
302	      s2_out_exp_shifted_reg          <= 'd0;
303	      s2_out_may_be_subnormal_reg     <= 'd0;
304	      s2_out_rm_reg                   <= 'd0;
305	      ctrl_c_reg2                     <= 'd0;
306	      ctrl_rm_reg2                    <= 'd0;
307	      ctrl_reg_idxw_reg2              <= 'd0;
308	      ctrl_warpid_reg2                <= 'd0;
309	    end
310	    else if(reg_en2) begin
311	      s2_out_special_case_valid_reg   <= s2_out_special_case_valid  ;   
312	      s2_out_special_case_nan_reg     <= s2_out_special_case_nan    ;
313	      s2_out_special_case_inf_reg     <= s2_out_special_case_inf    ;
314	      s2_out_special_case_inv_reg     <= s2_out_special_case_inv    ;
315	      s2_out_special_case_haszero_reg <= s2_out_special_case_haszero;
316	      s2_out_earyl_overflow_reg       <= s2_out_earyl_overflow      ;
317	      s2_out_prod_reg                 <= s2_out_prod                ;
318	      s2_out_prod_sign_reg            <= s2_out_prod_sign           ;
319	      s2_out_shift_amt_reg            <= s2_out_shift_amt           ;
320	      s2_out_exp_shifted_reg          <= s2_out_exp_shifted         ;
321	      s2_out_may_be_subnormal_reg     <= s2_out_may_be_subnormal    ;
322	      s2_out_rm_reg                   <= s2_out_rm                  ;
323	      ctrl_c_reg2                     <= ctrl_c_reg1                ; 
324	      ctrl_rm_reg2                    <= ctrl_rm_reg1               ;
325	      ctrl_reg_idxw_reg2              <= ctrl_reg_idxw_reg1         ;
326	      ctrl_warpid_reg2                <= ctrl_warpid_reg1           ;
327	    end
328	    else begin
329	      s2_out_special_case_valid_reg   <= s2_out_special_case_valid_reg  ;  
330	      s2_out_special_case_nan_reg     <= s2_out_special_case_nan_reg    ;
331	      s2_out_special_case_inf_reg     <= s2_out_special_case_inf_reg    ;
332	      s2_out_special_case_inv_reg     <= s2_out_special_case_inv_reg    ;
333	      s2_out_special_case_haszero_reg <= s2_out_special_case_haszero_reg;
334	      s2_out_earyl_overflow_reg       <= s2_out_earyl_overflow_reg      ;
335	      s2_out_prod_reg                 <= s2_out_prod_reg                ;
336	      s2_out_prod_sign_reg            <= s2_out_prod_sign_reg           ;
337	      s2_out_shift_amt_reg            <= s2_out_shift_amt_reg           ;
338	      s2_out_exp_shifted_reg          <= s2_out_exp_shifted_reg         ;
339	      s2_out_may_be_subnormal_reg     <= s2_out_may_be_subnormal_reg    ;
340	      s2_out_rm_reg                   <= s2_out_rm_reg                  ;
341	      ctrl_c_reg2                     <= ctrl_c_reg2                    ;
342	      ctrl_rm_reg2                    <= ctrl_rm_reg2                   ;
343	      ctrl_reg_idxw_reg2              <= ctrl_reg_idxw_reg2             ;
344	      ctrl_warpid_reg2                <= ctrl_warpid_reg2               ;
345	    end
346	  end
347	
348	  //例化fmul_s3
349	  fmul_s3 #(
350	    .EXPWIDTH (EXPWIDTH ),
351	    .PRECISION(PRECISION)
352	  )
353	  U_fmul_s3 (
354	    .in_special_case_valid_i  (s2_out_special_case_valid_reg  ),  
355	    .in_special_case_nan_i    (s2_out_special_case_nan_reg    ),
356	    .in_special_case_inf_i    (s2_out_special_case_inf_reg    ),
357	    .in_special_case_inv_i    (s2_out_special_case_inv_reg    ),
358	    .in_special_case_haszero_i(s2_out_special_case_haszero_reg),
359	    .in_earyl_overflow_i      (s2_out_earyl_overflow_reg      ),
360	    .in_prod_i                (s2_out_prod_reg                ),
361	    .in_prod_sign_i           (s2_out_prod_sign_reg           ),
362	    .in_shift_amt_i           (s2_out_shift_amt_reg           ),
363	    .in_exp_shifted_i         (s2_out_exp_shifted_reg         ),
364	    .in_may_be_subnormal_i    (s2_out_may_be_subnormal_reg    ),
365	    .in_rm_i                  (s2_out_rm_reg                  ),
366	    .result_o                 (result_o                       ),
367	    .fflags_o                 (fflags_o                       ),
368	    .to_fadd_fp_prod_sign_o   (s3_out_to_fadd_fp_prod_sign    ),                          
369	    .to_fadd_fp_prod_exp_o    (s3_out_to_fadd_fp_prod_exp     ),                          
370	    .to_fadd_fp_prod_sig_o    (s3_out_to_fadd_fp_prod_sig     ),                          
371	    .to_fadd_is_nan_o         (s3_out_to_fadd_is_nan          ),                          
372	    .to_fadd_is_inf_o         (s3_out_to_fadd_is_inf          ),                          
373	    .to_fadd_is_inv_o         (s3_out_to_fadd_is_inv          ),                          
374	    .to_fadd_overflow_o       (s3_out_to_fadd_overflow        )                          
375	  );
376	
377	  assign  ctrl_c_o        = ctrl_c_reg2       ;
378	  assign  ctrl_rm_o       = ctrl_rm_reg2      ;
379	  assign  ctrl_reg_idxw_o = ctrl_reg_idxw_reg2;
380	  assign  ctrl_warpid_o   = ctrl_warpid_reg2  ;
381	
382	endmodule
383

