11	// Author: Gu, Zihan
12	// Description:
13	`timescale 1ns/1ns
14	`include "define.v"
15	
16	module tc_add_pipe #(
17	  parameter EXPWIDTH  = 8,
18	  parameter PRECISION = 24,
19	  parameter LATENCY   = 2
20	)
21	(
22	  input                                 clk               ,
23	  input                                 rst_n             ,
24	
25	  //input   [2:0]                         op_i              ,
26	  input   [EXPWIDTH+PRECISION-1:0]      a_i               ,
27	  input   [EXPWIDTH+PRECISION-1:0]      b_i               ,
28	  //input   [EXPWIDTH+PRECISION-1:0]      c_i               ,
29	  input   [2:0]                         rm_i              ,
30	  input   [EXPWIDTH+PRECISION-1:0]      ctrl_c_i          ,
31	  input   [2:0]                         ctrl_rm_i         ,
32	  input   [7:0]                         ctrl_reg_idxw_i   ,
33	  input   [`DEPTH_WARP-1:0]             ctrl_warpid_i     ,
34	
35	  input                                 in_valid_i        ,
36	  input                                 out_ready_i       ,
37	
38	  output                                in_ready_o        ,
39	  output                                out_valid_o       ,
40	
41	  output  [EXPWIDTH+PRECISION-1:0]      result_o          ,
42	  output  [4:0]                         fflags_o          ,
43	  output  [EXPWIDTH+PRECISION-1:0]      ctrl_c_o          ,
44	  output  [2:0]                         ctrl_rm_o         ,
45	  output  [7:0]                         ctrl_reg_idxw_o   ,
46	  output  [`DEPTH_WARP-1:0]             ctrl_warpid_o     
47	);
48	
49	  reg     [EXPWIDTH+PRECISION-1:0]      a_reg       ;
50	  reg     [EXPWIDTH+PRECISION-1:0]      b_reg       ;
51	  reg     [2:0]                         rm_reg      ;
52	  wire    [EXPWIDTH+2*PRECISION-1:0]    s1_in_a     ;
53	  wire    [EXPWIDTH+2*PRECISION-1:0]    s1_in_b     ;
54	  //ctrl reg
55	  reg  [EXPWIDTH+PRECISION-1:0]ctrl_c_reg1          ;
56	  reg  [2:0]                   ctrl_rm_reg1         ;
57	  reg  [7:0]                   ctrl_reg_idxw_reg1   ;
58	  reg  [`DEPTH_WARP-1:0]       ctrl_warpid_reg1     ;
59	  reg  [EXPWIDTH+PRECISION-1:0]ctrl_c_reg2          ;
60	  reg  [2:0]                   ctrl_rm_reg2         ;
61	  reg  [7:0]                   ctrl_reg_idxw_reg2   ;
62	  reg  [`DEPTH_WARP-1:0]       ctrl_warpid_reg2     ;
63	  //for pipeline reg valid: latency = 2
64	  reg                          in_valid_reg1;
65	  reg                          in_valid_reg2;
66	  wire                         reg_en1      ;
67	  wire                         reg_en2      ;
68	  //s1 output
69	  wire [2:0]                   s1_out_rm                      ; 
70	  wire                         s1_out_far_sign                ; 
71	  wire [EXPWIDTH-1:0]          s1_out_far_exp                 ; 
72	  wire [PRECISION+2:0]         s1_out_far_sig                 ; 
73	  wire                         s1_out_near_sign               ; 
74	  wire [EXPWIDTH-1:0]          s1_out_near_exp                ; 
75	  wire [PRECISION+2:0]         s1_out_near_sig                ; 
76	  wire                         s1_out_special_case_valid      ; 
77	  wire                         s1_out_special_case_iv         ; 
78	  wire                         s1_out_special_case_nan        ; 
79	  wire                         s1_out_special_case_inf_sign   ; 
80	  wire                         s1_out_small_add               ; 
81	  wire                         s1_out_far_mul_of              ; 
82	  wire                         s1_out_near_sig_is_zero        ; 
83	  wire                         s1_out_sel_far_path            ;   
84	  //s1 output reg
85	  reg  [2:0]                   s1_out_rm_reg                      ; 
86	  reg                          s1_out_far_sign_reg                ; 
87	  reg  [EXPWIDTH-1:0]          s1_out_far_exp_reg                 ; 
88	  reg  [PRECISION+2:0]         s1_out_far_sig_reg                 ; 
89	  reg                          s1_out_near_sign_reg               ; 
90	  reg  [EXPWIDTH-1:0]          s1_out_near_exp_reg                ; 
91	  reg  [PRECISION+2:0]         s1_out_near_sig_reg                ; 
92	  reg                          s1_out_special_case_valid_reg      ; 
93	  reg                          s1_out_special_case_iv_reg         ; 
94	  reg                          s1_out_special_case_nan_reg        ; 
95	  //reg                          s1_out_special_case_inf_sign_reg   ; 
96	  //reg                          s1_out_small_add_reg               ; 
97	  reg                          s1_out_far_mul_of_reg              ; 
98	  reg                          s1_out_near_sig_is_zero_reg        ; 
99	  reg                          s1_out_sel_far_path_reg            ;
100	  //s2 output
101	  wire [EXPWIDTH+PRECISION-1:0]s2_out_result                  ;
102	  wire [4:0]                   s2_out_fflags                  ;
103	
104	  always@(posedge clk or negedge rst_n) begin
105	    if(!rst_n) begin
106	      in_valid_reg1 <= 'd0 ;
107	      in_valid_reg2 <= 'd0 ;
108	    end
109	    else begin
110	      if(!(!out_ready_i && in_valid_reg1 && in_valid_reg2)) begin
111	        in_valid_reg1 <= in_valid_i   ;
112	      end
113	      else begin
114	        in_valid_reg1 <= in_valid_reg1;
115	      end
116	      if(!(!out_ready_i && in_valid_reg2)) begin        
117	        in_valid_reg2 <= in_valid_reg1;
118	      end
119	      else begin
120	        in_valid_reg2 <= in_valid_reg2;
121	      end
122	    end
123	  end
124	
125	  assign reg_en1 = in_valid_i && !(in_valid_reg1 && in_valid_reg2 && !out_ready_i) ;
126	  assign reg_en2 = in_valid_reg1 && !(in_valid_reg2 && !out_ready_i)               ;
127	
128	  //for valid and ready
129	  assign in_ready_o  = !(!out_ready_i && in_valid_reg1 && in_valid_reg2) ;
130	  assign out_valid_o = in_valid_reg2                                     ;
131	
132	  always@(posedge clk or negedge rst_n) begin
133	    if(!rst_n) begin
134	      a_reg              <= 'd0;
135	      b_reg              <= 'd0;
136	      rm_reg             <= 'd0;
137	      ctrl_c_reg1        <= 'd0;
138	      ctrl_rm_reg1       <= 'd0;
139	      ctrl_reg_idxw_reg1 <= 'd0;
140	      ctrl_warpid_reg1   <= 'd0;
141	    end
142	    else if(reg_en1) begin
143	      a_reg              <= a_i            ;
144	      b_reg              <= b_i            ;
145	      rm_reg             <= rm_i           ;
146	      ctrl_c_reg1        <= ctrl_c_i       ;
147	      ctrl_rm_reg1       <= ctrl_rm_i      ;
148	      ctrl_reg_idxw_reg1 <= ctrl_reg_idxw_i;
149	      ctrl_warpid_reg1   <= ctrl_warpid_i  ;
150	    end
151	    else begin
152	      a_reg  <= a_reg                         ;
153	      b_reg  <= b_reg                         ;
154	      rm_reg <= rm_reg                        ;
155	      ctrl_c_reg1        <= ctrl_c_reg1       ;
156	      ctrl_rm_reg1       <= ctrl_rm_reg1      ;
157	      ctrl_reg_idxw_reg1 <= ctrl_reg_idxw_reg1;
158	      ctrl_warpid_reg1   <= ctrl_warpid_reg1  ;
159	    end
160	  end
161	
162	  assign  s1_in_a = {a_reg,{PRECISION{1'b0}}};
163	  assign  s1_in_b = {b_reg,{PRECISION{1'b0}}};
164	
165	  //例化fadd_s1
166	  fadd_s1 #(
167	    .EXPWIDTH  (EXPWIDTH  ),
168	    .PRECISION (2*PRECISION ),
169	    .OUTPC     (PRECISION )
170	  )
171	  U_fadd_s1 (
172	    .a_i                        (s1_in_a                     ),  
173	    .b_i                        (s1_in_b                     ), 
174	    .rm_i                       (rm_reg                      ),
175	    .b_inter_valid_i            (1'd0                        ),
176	    .b_inter_flags_is_nan_i     (1'd0                        ),
177	    .b_inter_flags_is_inf_i     (1'd0                        ),
178	    .b_inter_flags_is_inv_i     (1'd0                        ),
179	    .b_inter_flags_overflow_i   (1'd0                        ),
180	    .out_rm_o                   (s1_out_rm                   ),
181	    .out_far_sign_o             (s1_out_far_sign             ),
182	    .out_far_exp_o              (s1_out_far_exp              ),
183	    .out_far_sig_o              (s1_out_far_sig              ),
184	    .out_near_sign_o            (s1_out_near_sign            ),
185	    .out_near_exp_o             (s1_out_near_exp             ),
186	    .out_near_sig_o             (s1_out_near_sig             ),
187	    .out_special_case_valid_o   (s1_out_special_case_valid   ),
188	    .out_special_case_iv_o      (s1_out_special_case_iv      ),
189	    .out_special_case_nan_o     (s1_out_special_case_nan     ),
190	    .out_special_case_inf_sign_o(s1_out_special_case_inf_sign),
191	    .out_small_add_o            (s1_out_small_add            ),
192	    .out_far_mul_of_o           (s1_out_far_mul_of           ),
193	    .out_near_sig_is_zero_o     (s1_out_near_sig_is_zero     ),
194	    .out_sel_far_path_o         (s1_out_sel_far_path         )
195	  );  
196	
197	  //寄存s1的输出
198	  always@(posedge clk or negedge rst_n) begin
199	    if(!rst_n) begin
200	      s1_out_rm_reg                    <= 'd0;   
201	      s1_out_far_sign_reg              <= 'd0;
202	      s1_out_far_exp_reg               <= 'd0;
203	      s1_out_far_sig_reg               <= 'd0;
204	      s1_out_near_sign_reg             <= 'd0;
205	      s1_out_near_exp_reg              <= 'd0;
206	      s1_out_near_sig_reg              <= 'd0;
207	      s1_out_special_case_valid_reg    <= 'd0;
208	      s1_out_special_case_iv_reg       <= 'd0;
209	      s1_out_special_case_nan_reg      <= 'd0;
210	      //s1_out_special_case_inf_sign_reg <= 'd0;
211	      //s1_out_small_add_reg             <= 'd0;
212	      s1_out_far_mul_of_reg            <= 'd0;
213	      s1_out_near_sig_is_zero_reg      <= 'd0;
214	      s1_out_sel_far_path_reg          <= 'd0;
215	      ctrl_c_reg2                      <= 'd0;
216	      ctrl_rm_reg2                     <= 'd0;
217	      ctrl_reg_idxw_reg2               <= 'd0;
218	      ctrl_warpid_reg2                 <= 'd0;
219	    end
220	    else if(reg_en2) begin
221	      s1_out_rm_reg                    <= s1_out_rm                   ;  
222	      s1_out_far_sign_reg              <= s1_out_far_sign             ;
223	      s1_out_far_exp_reg               <= s1_out_far_exp              ;
224	      s1_out_far_sig_reg               <= s1_out_far_sig              ;
225	      s1_out_near_sign_reg             <= s1_out_near_sign            ;
226	      s1_out_near_exp_reg              <= s1_out_near_exp             ;
227	      s1_out_near_sig_reg              <= s1_out_near_sig             ;
228	      s1_out_special_case_valid_reg    <= s1_out_special_case_valid   ;
229	      s1_out_special_case_iv_reg       <= s1_out_special_case_iv      ;
230	      s1_out_special_case_nan_reg      <= s1_out_special_case_nan     ;
231	      //s1_out_special_case_inf_sign_reg <= s1_out_special_case_inf_sign;
232	      //s1_out_small_add_reg             <= s1_out_small_add            ;
233	      s1_out_far_mul_of_reg            <= s1_out_far_mul_of           ;
234	      s1_out_near_sig_is_zero_reg      <= s1_out_near_sig_is_zero     ;
235	      s1_out_sel_far_path_reg          <= s1_out_sel_far_path         ;
236	      ctrl_c_reg2                      <= ctrl_c_reg1                 ;
237	      ctrl_rm_reg2                     <= ctrl_rm_reg1                ;
238	      ctrl_reg_idxw_reg2               <= ctrl_reg_idxw_reg1          ;
239	      ctrl_warpid_reg2                 <= ctrl_warpid_reg1            ;
240	    end
241	    else begin
242	      s1_out_rm_reg                    <= s1_out_rm_reg                   ;
243	      s1_out_far_sign_reg              <= s1_out_far_sign_reg             ;  
244	      s1_out_far_exp_reg               <= s1_out_far_exp_reg              ;
245	      s1_out_far_sig_reg               <= s1_out_far_sig_reg              ;
246	      s1_out_near_sign_reg             <= s1_out_near_sign_reg            ;
247	      s1_out_near_exp_reg              <= s1_out_near_exp_reg             ;
248	      s1_out_near_sig_reg              <= s1_out_near_sig_reg             ;
249	      s1_out_special_case_valid_reg    <= s1_out_special_case_valid_reg   ;
250	      s1_out_special_case_iv_reg       <= s1_out_special_case_iv_reg      ;
251	      s1_out_special_case_nan_reg      <= s1_out_special_case_nan_reg     ;
252	      //s1_out_special_case_inf_sign_reg <= s1_out_special_case_inf_sign_reg;
253	      //s1_out_small_add_reg             <= s1_out_small_add_reg            ;
254	      s1_out_far_mul_of_reg            <= s1_out_far_mul_of_reg           ;
255	      s1_out_near_sig_is_zero_reg      <= s1_out_near_sig_is_zero_reg     ;
256	      s1_out_sel_far_path_reg          <= s1_out_sel_far_path_reg         ;
257	      ctrl_c_reg2                      <= ctrl_c_reg2                     ;
258	      ctrl_rm_reg2                     <= ctrl_rm_reg2                    ;
259	      ctrl_reg_idxw_reg2               <= ctrl_reg_idxw_reg2              ;
260	      ctrl_warpid_reg2                 <= ctrl_warpid_reg2                ;
261	    end
262	  end
263	
264	  //例化fadd_s2
265	  fadd_s2 #(
266	    .EXPWIDTH  (EXPWIDTH  ),
267	    .PRECISION (PRECISION )
268	  )
269	  U_fadd_s2 ( 
270	    .in_rm_i                   (s1_out_rm_reg                   ),                        
271	    .in_far_sign_i             (s1_out_far_sign_reg             ),
272	    .in_far_exp_i              (s1_out_far_exp_reg              ),
273	    .in_far_sig_i              (s1_out_far_sig_reg              ),
274	    .in_near_sign_i            (s1_out_near_sign_reg            ),
275	    .in_near_exp_i             (s1_out_near_exp_reg             ),
276	    .in_near_sig_i             (s1_out_near_sig_reg             ),
277	    .in_special_case_valid_i   (s1_out_special_case_valid_reg   ),
278	    .in_special_case_iv_i      (s1_out_special_case_iv_reg      ),
279	    .in_special_case_nan_i     (s1_out_special_case_nan_reg     ),
280	    //.in_special_case_inf_sign_i(s1_out_special_case_inf_sign_reg),
281	    //.in_small_add_i            (s1_out_small_add_reg            ),
282	    .in_far_mul_of_i           (s1_out_far_mul_of_reg           ),
283	    .in_near_sig_is_zero_i     (s1_out_near_sig_is_zero_reg     ),
284	    .in_sel_far_path_i         (s1_out_sel_far_path_reg         ),
285	    .out_result_o              (result_o                        ), 
286	    .out_fflags_o              (fflags_o                        )
287	  );
288	
289	  assign  ctrl_c_o        = ctrl_c_reg2       ;
290	  assign  ctrl_rm_o       = ctrl_rm_reg2      ;
291	  assign  ctrl_reg_idxw_o = ctrl_reg_idxw_reg2;
292	  assign  ctrl_warpid_o   = ctrl_warpid_reg2  ;
293	
294	endmodule
