55	  wire a_is_snan     , b_is_snan      ;
56	  //wire a_is_qnan     , b_is_qnan      ;
57	
58	  assign a_exp_is_zero  = a_i[EXPWIDTH+PRECISION-2:PRECISION-1] == 'd0 ;
