60	  assign a_exp_is_ones  = &a_i[EXPWIDTH+PRECISION-2:PRECISION-1]       ;
61	  assign b_exp_is_ones  = &b_i[EXPWIDTH+PRECISION-2:PRECISION-1]       ;
62	  assign a_sig_is_zero  = a_i[PRECISION-2:0] == 'd0                    ;
63	  assign b_sig_is_zero  = b_i[PRECISION-2:0] == 'd0                    ;
