90	  assign raw_b_exp  = b_i[EXPWIDTH+PRECISION-2:PRECISION-1] | {{(EXPWIDTH-1){1'b0}},b_exp_is_zero};
91	  assign raw_a_sig  = {!a_exp_is_zero,a_i[PRECISION-2:0]}                                         ;
92	  assign raw_b_sig  = {!b_exp_is_zero,b_i[PRECISION-2:0]}                                         ;
93	  assign eff_sub    = raw_a_sign ^ raw_b_sign                                                     ;
94	  assign small_add  = a_exp_is_zero && b_exp_is_zero                                              ;
95	
96	  //deal special cases
97	  wire b_isnan             ;
98	  wire b_issnan            ;
99	  wire b_isinf             ;
100	  wire special_path_has_nan ;
101	  wire special_path_has_snan;
102	  wire special_path_has_inf ;
