111	  assign special_path_has_snan = a_is_snan || b_issnan                               ;
112	  assign special_path_has_inf  = a_is_inf || b_isinf                                 ;
113	  assign special_path_inf_iv   = a_is_inf && b_isinf && eff_sub                      ;
114	  assign special_path_iv       = special_path_has_snan || special_path_inf_iv        ;
115	  assign special_case_happen   = special_path_has_nan || special_path_has_inf        ;
