132	  wire [EXPWIDTH-1:0]  far_path_in_a_exp   ;
133	  wire [PRECISION-1:0] far_path_in_a_sig   ;
134	  //wire                 far_path_in_b_sign  ;
135	  //wire [EXPWIDTH-1:0]  far_path_in_b_exp   ;
136	  wire [PRECISION-1:0] far_path_in_b_sig   ;
137	  wire [EXPWIDTH-1:0]  far_path_in_expdiff ;
