188	  wire                 near_path_out_sig_is_zero;
189	  
190	  assign near_path_exp_neq = raw_a_exp[1:0] != raw_b_exp[1:0];
191	  
192	  near_path #(
193	    .EXPWIDTH  (EXPWIDTH ),
194	    .PRECISION (PRECISION),
195	    .OUTPC     (OUTPC    )
196	  )
197	  near_path_mods_0 (
198	    .a_sign_i       (raw_a_sign             ),
199	    .a_exp_i        (raw_a_exp              ),
