11	// Author: Tan, Zhiyuan
12	// Description:
13	
14	`timescale 1ns/1ns
15	
16	`include "define.v"
17	//`include "fpu_ops.v"
18	
19	module fadd_s2 #(
20	  parameter EXPWIDTH  = 8,
21	  parameter PRECISION = 24
22	)
23	(
24	  input  [2:0]                    in_rm_i                       ,
25	  input                           in_far_sign_i                 ,
26	  input  [EXPWIDTH-1:0]           in_far_exp_i                  ,
27	  input  [PRECISION+2:0]          in_far_sig_i                  ,
28	  input                           in_near_sign_i                ,
29	  input  [EXPWIDTH-1:0]           in_near_exp_i                 ,
30	  input  [PRECISION+2:0]          in_near_sig_i                 ,
31	  input                           in_special_case_valid_i       ,
32	  input                           in_special_case_iv_i          ,
33	  input                           in_special_case_nan_i         ,
34	  //input                           in_special_case_inf_sign_i    ,
35	  //input                           in_small_add_i                ,
36	  input                           in_far_mul_of_i               ,
37	  input                           in_near_sig_is_zero_i         ,
38	  input                           in_sel_far_path_i             ,
39	  output [EXPWIDTH+PRECISION-1:0] out_result_o                  ,
40	  output [4:0]                    out_fflags_o                   
41	);
42	
43	  parameter NEAR_INV    = (1<<EXPWIDTH)-2              ;
44	  parameter INV         = (1<<EXPWIDTH)-1              ;
45	
46	  //special output
47	  wire [EXPWIDTH+PRECISION-1:0] special_path_result;
48	  wire [4:0]                    special_path_fflags;
49	
50	  assign special_path_result = in_special_case_nan_i ? {1'b0,{(EXPWIDTH+1){1'b1}},{(PRECISION-2){1'b0}}} : {1'b0,{EXPWIDTH{1'b1}},{(PRECISION-1){1'b0}}};
51	  assign special_path_fflags = {in_special_case_iv_i,4'b0000};
52	
53	  //far_path
54	  wire [PRECISION+1:0] far_path_rounder_0_in     ;
55	  wire [PRECISION-2:0] far_path_rounder_0_out    ;
56	  wire                 far_path_rounder_0_inexact;
57	  wire                 far_path_rounder_0_cout   ;
58	  wire                 far_path_rounder_0_r_up   ;
59	  wire                 far_path_tininess         ;
60	
61	  assign far_path_rounder_0_in = {in_far_sig_i[PRECISION:0],1'b0} ;
62	
63	  rounding #(
64	    .WIDTH (PRECISION-1)
65	  )
66	  far_path_rounder_0 (
67	    .in       (far_path_rounder_0_in[PRECISION+1:3]),   
68	    .sign     (in_far_sign_i                       ),
69	    .roundin  (far_path_rounder_0_in[2]            ),
70	    .stickyin (|far_path_rounder_0_in[1:0]         ),
71	    .rm       (in_rm_i                             ),
72	    .out      (far_path_rounder_0_out              ),
73	    .inexact  (far_path_rounder_0_inexact          ),
74	    .cout     (far_path_rounder_0_cout             ),
75	    .r_up     (far_path_rounder_0_r_up             )
76	  );
77	
78	  assign far_path_tininess = (in_far_sig_i[PRECISION+2:PRECISION+1]==2'b00) || ((in_far_sig_i[PRECISION+2:PRECISION+1]==2'b01)&&!far_path_rounder_0_cout) ;
79	
80	
81	  wire [PRECISION+1:0] far_path_rounder_1_in     ;
82	  wire [PRECISION-2:0] far_path_rounder_1_out    ;
83	  wire                 far_path_rounder_1_inexact;
84	  wire                 far_path_rounder_1_cout   ;
85	  wire                 far_path_rounder_1_r_up   ;
86	
87	  assign far_path_rounder_1_in = in_far_sig_i[PRECISION+1:0] ;
88	
89	  rounding #(
90	    .WIDTH (PRECISION-1)
91	  )
92	  far_path_rounder_1 (
93	    .in       (far_path_rounder_1_in[PRECISION+1:3]),   
94	    .sign     (in_far_sign_i                       ),
95	    .roundin  (far_path_rounder_1_in[2]            ),
96	    .stickyin (|far_path_rounder_1_in[1:0]         ),
97	    .rm       (in_rm_i                             ),
98	    .out      (far_path_rounder_1_out              ),
99	    .inexact  (far_path_rounder_1_inexact          ),
100	    .cout     (far_path_rounder_1_cout             ),
101	    .r_up     (far_path_rounder_1_r_up             )
102	  );
103	
104	  wire [EXPWIDTH-1:0]           far_path_exp_rounded      ;
105	  wire [PRECISION-2:0]          far_path_sig_rounded      ;
106	  wire                          far_path_mul_of           ;
107	  wire                          far_path_may_uf           ;
108	  wire                          far_path_of_before_rounded;
109	  wire                          far_path_of_after_rounded ;
110	  wire                          far_path_of               ;
111	  wire                          far_path_ix               ;
112	  wire                          far_path_uf               ;
113	  wire [EXPWIDTH+PRECISION-1:0] far_path_result           ;
114	
115	  assign far_path_exp_rounded       = far_path_rounder_1_cout + in_far_exp_i                                    ;
116	  assign far_path_sig_rounded       = far_path_rounder_1_out                                                    ;
117	  assign far_path_mul_of            = in_far_mul_of_i                                                           ;
118	  assign far_path_may_uf            = far_path_tininess && !far_path_mul_of                                     ;
119	  assign far_path_of_before_rounded = in_far_exp_i == INV                                                       ;
120	  assign far_path_of_after_rounded  = far_path_rounder_1_cout && (in_far_exp_i==NEAR_INV)                       ;
121	  assign far_path_of                = far_path_of_before_rounded || far_path_of_after_rounded || in_far_mul_of_i;
122	  assign far_path_ix                = far_path_rounder_1_inexact || far_path_of                                 ;
123	  assign far_path_uf                = far_path_may_uf && far_path_ix                                            ;
124	  assign far_path_result            = {in_far_sign_i,far_path_exp_rounded,far_path_sig_rounded}                 ;
125	
126	  //near path
127	  wire near_path_is_zero;
128	
129	  assign near_path_is_zero = (in_near_exp_i=='d0) && in_near_sig_is_zero_i;
130	
131	  wire [PRECISION+1:0] near_path_rounder_0_in     ;
132	  wire [PRECISION-2:0] near_path_rounder_0_out    ;
133	  wire                 near_path_rounder_0_inexact;
134	  wire                 near_path_rounder_0_cout   ;
135	  wire                 near_path_rounder_0_r_up   ;
136	  wire                 near_path_tininess         ;
137	
138	  assign near_path_rounder_0_in = {in_near_sig_i[PRECISION:0],1'b0} ;
139	
140	  rounding #(
141	    .WIDTH (PRECISION-1)
142	  )
143	  near_path_rounder_0 (
144	    .in       (near_path_rounder_0_in[PRECISION+1:3]),   
145	    .sign     (in_near_sign_i                       ),
146	    .roundin  (near_path_rounder_0_in[2]            ),
147	    .stickyin (|near_path_rounder_0_in[1:0]         ),
148	    .rm       (in_rm_i                              ),
149	    .out      (near_path_rounder_0_out              ),
150	    .inexact  (near_path_rounder_0_inexact          ),
151	    .cout     (near_path_rounder_0_cout             ),
152	    .r_up     (near_path_rounder_0_r_up             )
153	  );
154	
155	  assign near_path_tininess = (in_near_sig_i[PRECISION+2:PRECISION+1]==2'b00) || ((in_near_sig_i[PRECISION+2:PRECISION+1]==2'b01)&&!near_path_rounder_0_cout) ;
156	
157	
158	  wire [PRECISION+1:0] near_path_rounder_1_in     ;
159	  wire [PRECISION-2:0] near_path_rounder_1_out    ;
160	  wire                 near_path_rounder_1_inexact;
161	  wire                 near_path_rounder_1_cout   ;
162	  wire                 near_path_rounder_1_r_up   ;
163	
164	  assign near_path_rounder_1_in = in_near_sig_i[PRECISION+1:0] ;
165	
166	  rounding #(
167	    .WIDTH (PRECISION-1)
168	  )
169	  near_path_rounder_1 (
170	    .in       (near_path_rounder_1_in[PRECISION+1:3]),   
171	    .sign     (in_near_sign_i                       ),
172	    .roundin  (near_path_rounder_1_in[2]            ),
173	    .stickyin (|near_path_rounder_1_in[1:0]         ),
174	    .rm       (in_rm_i                              ),
175	    .out      (near_path_rounder_1_out              ),
176	    .inexact  (near_path_rounder_1_inexact          ),
177	    .cout     (near_path_rounder_1_cout             ),
178	    .r_up     (near_path_rounder_1_r_up             )
179	  );
180	
181	  wire [EXPWIDTH-1:0]           near_path_exp_rounded;
182	  wire [PRECISION-2:0]          near_path_sig_rounded;
183	  wire                          near_path_zero_sign  ;
184	  wire                          near_path_sign       ;
185	  wire [EXPWIDTH+PRECISION-1:0] near_path_result     ;
186	  wire                          near_path_of         ;
187	  wire                          near_path_ix         ;
188	  wire                          near_path_uf         ;
189	
190	  assign near_path_exp_rounded = near_path_rounder_1_cout + in_near_exp_i                                            ;
191	  assign near_path_sig_rounded = near_path_rounder_1_out                                                             ;
192	  assign near_path_zero_sign   = in_rm_i == `RDN                                                                     ;
193	  assign near_path_sign        = (in_near_sign_i && !near_path_is_zero) || (near_path_zero_sign && near_path_is_zero);
194	  assign near_path_result      = {near_path_sign,near_path_exp_rounded,near_path_sig_rounded}                        ;
195	  assign near_path_of          = near_path_exp_rounded == {EXPWIDTH{1'b1}}                                           ;
196	  assign near_path_ix          = near_path_rounder_1_inexact || near_path_of                                         ;
197	  assign near_path_uf          = near_path_tininess && near_path_ix                                                  ;
198	
199	  //common output
200	  wire                          common_overflow       ;
201	  wire                          common_overflow_sign  ;
202	  wire                          rmin                  ;
203	  wire [EXPWIDTH-1:0]           common_overflow_exp   ;
204	  wire [PRECISION-2:0]          common_overflow_sig   ;
205	  wire                          common_underflow      ;
206	  wire                          common_inexact        ;
207	  wire [4:0]                    common_fflags         ;
208	  wire [EXPWIDTH+PRECISION-1:0] common_overflow_result;
209	
210	  assign common_overflow        = (in_sel_far_path_i&&far_path_of) || (!in_sel_far_path_i&&near_path_of)                  ;
211	  assign common_overflow_sign   = in_sel_far_path_i ? in_far_sign_i : in_near_sign_i                                      ;
212	  assign rmin                   = (in_rm_i==`RTZ) || (in_rm_i==`RDN && !in_far_sign_i) || (in_rm_i==`RUP && in_far_sign_i);
213	  assign common_overflow_exp    = rmin ? NEAR_INV : INV                                                                   ;
214	  assign common_overflow_sig    = rmin ? {(PRECISION-1){1'b1}} : {(PRECISION-1){1'b0}}                                    ;
215	  assign common_underflow       = (in_sel_far_path_i&&far_path_uf) || (!in_sel_far_path_i&&near_path_uf)                  ;
216	  assign common_inexact         = (in_sel_far_path_i&&far_path_ix) || (!in_sel_far_path_i&&near_path_ix)                  ;
217	  assign common_fflags          = {1'b0,1'b0,common_overflow,common_underflow,common_inexact}                             ;
218	  assign common_overflow_result = {common_overflow_sign,common_overflow_exp,common_overflow_sig}                          ;
219	
220	  //outputs
221	  assign out_result_o = in_special_case_valid_i ? special_path_result : (common_overflow ? common_overflow_result : (in_sel_far_path_i ? far_path_result : near_path_result)) ;
222	  assign out_fflags_o = in_special_case_valid_i ? special_path_fflags : common_fflags ;
223	
224	endmodule
