1	/*
2	 * Copyright (c) 2023-2024 C*Core Technology Co.,Ltd,Suzhou.
3	 * Ventus-RTL is licensed under Mulan PSL v2.
4	 * You can use this software according to the terms and conditions of the Mulan PSL v2.
5	 * You may obtain a copy of Mulan PSL v2 at:
6	 *          http://license.coscl.org.cn/MulanPSL2
7	 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND,
8	 * EITHER EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT,
9	 * MERCHANTABILITY OR FIT FOR A PARTICULAR PURPOSE.
10	 * See the Mulan PSL v2 for more details. */
11	// Author: Tan, Zhiyuan
12	// Description:
13	
14	`timescale 1ns/1ns
15	
16	module fmul_s1 #(
17	  parameter EXPWIDTH  = 8,
18	  parameter PRECISION = 24
19	)(
20	  input  [EXPWIDTH+PRECISION-1:0] a_i                       ,
21	  input  [EXPWIDTH+PRECISION-1:0] b_i                       ,
22	  input  [2:0]                    rm_i                      ,
23	  output                          out_special_case_valid_o  ,
24	  output                          out_special_case_nan_o    ,
25	  output                          out_special_case_inf_o    ,
26	  output                          out_special_case_inv_o    ,
27	  output                          out_special_case_haszero_o,
28	  output                          out_earyl_overflow_o      ,
29	  output                          out_prod_sign_o           ,
30	  output [EXPWIDTH:0]             out_shift_amt_o           ,
31	  output [EXPWIDTH:0]             out_exp_shifted_o         ,
32	  output                          out_may_be_subnormal_o    ,
33	  output [2:0]                    out_rm_o
34	);
35	
36	  parameter PADDINGBITS = PRECISION+2        ;
37	  parameter BIASINT     = (1<<(EXPWIDTH-1))-1;
38	  parameter MAXNORMEXP  = (1<<EXPWIDTH)-2    ;
39	
40	  //classify
41	  wire a_exp_is_zero , b_exp_is_zero  ;
42	  wire a_exp_is_ones , b_exp_is_ones  ;
43	  wire a_sig_is_zero , b_sig_is_zero  ;
44	  //wire a_is_subnormal, b_is_subnormal ;
45	  wire a_is_inf      , b_is_inf       ;
46	  wire a_is_zero     , b_is_zero      ;
47	  wire a_is_nan      , b_is_nan       ;
48	  wire a_is_snan     , b_is_snan      ;
49	  //wire a_is_qnan     , b_is_qnan      ;
50	
51	  assign a_exp_is_zero  = a_i[EXPWIDTH+PRECISION-2:PRECISION-1] == 'd0 ;
52	  assign b_exp_is_zero  = b_i[EXPWIDTH+PRECISION-2:PRECISION-1] == 'd0 ;
53	  assign a_exp_is_ones  = &a_i[EXPWIDTH+PRECISION-2:PRECISION-1]       ;
54	  assign b_exp_is_ones  = &b_i[EXPWIDTH+PRECISION-2:PRECISION-1]       ;
55	  assign a_sig_is_zero  = a_i[PRECISION-2:0] == 'd0                    ;
56	  assign b_sig_is_zero  = b_i[PRECISION-2:0] == 'd0                    ;
57	  //assign a_is_subnormal = a_exp_is_zero && !a_sig_is_zero              ;
58	  //assign b_is_subnormal = b_exp_is_zero && !b_sig_is_zero              ;
59	  assign a_is_inf       = a_exp_is_ones && a_sig_is_zero               ;
60	  assign b_is_inf       = b_exp_is_ones && b_sig_is_zero               ;
61	  assign a_is_zero      = a_exp_is_zero && a_sig_is_zero               ;
62	  assign b_is_zero      = b_exp_is_zero && b_sig_is_zero               ;
63	  assign a_is_nan       = a_exp_is_ones && !a_sig_is_zero              ;
64	  assign b_is_nan       = b_exp_is_ones && !b_sig_is_zero              ;
65	  assign a_is_snan      = a_is_nan && !a_i[PRECISION-2]                ;
66	  assign b_is_snan      = b_is_nan && !b_i[PRECISION-2]                ;
67	  //assign a_is_qnan      = a_is_nan && a_i[PRECISION-2]                 ;
68	  //assign b_is_qnan      = b_is_nan && b_i[PRECISION-2]                 ;
69	
70	  //sign, exp, sig
71	  wire                 raw_a_sign   ;
72	  wire                 raw_b_sign   ;
73	  wire [EXPWIDTH-1:0]  raw_a_exp    ;
74	  wire [EXPWIDTH-1:0]  raw_b_exp    ;
75	  wire [PRECISION-1:0] raw_a_sig    ;
76	  wire [PRECISION-1:0] raw_b_sig    ;
77	  wire                 prod_sign    ;
78	
79	  assign raw_a_sign      = a_i[EXPWIDTH+PRECISION-1]                                                   ;
80	  assign raw_b_sign      = b_i[EXPWIDTH+PRECISION-1]                                                   ;
81	  assign raw_a_exp       = a_i[EXPWIDTH+PRECISION-2:PRECISION-1] | {{(EXPWIDTH-1){1'b0}},a_exp_is_zero};
82	  assign raw_b_exp       = b_i[EXPWIDTH+PRECISION-2:PRECISION-1] | {{(EXPWIDTH-1){1'b0}},b_exp_is_zero};
83	  assign raw_a_sig       = {!a_exp_is_zero,a_i[PRECISION-2:0]}                                         ;
84	  assign raw_b_sig       = {!b_exp_is_zero,b_i[PRECISION-2:0]}                                         ; 
85	
86	  //output sign
87	  assign prod_sign       = raw_a_sign ^ raw_b_sign                              ; 
88	
89	  //shift calculation
90	  wire [EXPWIDTH:0]                exp_sum       ;
91	  wire [EXPWIDTH:0]                prod_exp      ;
92	  wire [EXPWIDTH+1:0]              shift_lim_sub ;
93	  wire                             prod_exp_uf   ;
94	  wire [EXPWIDTH:0]                shift_lim     ;
95	  wire                             prod_exp_ov   ;
96	  wire [PRECISION-1:0]             subnormal_sig ;
97	  wire [$clog2(PRECISION*2+2)-1:0] lzc           ;
98	  wire                             exceed_lim    ;
99	  wire [$clog2(PRECISION*2+2)-1:0] shift_amt     ;
100	  wire [EXPWIDTH:0]                exp_shifted   ;
101	
102	  assign exp_sum       = raw_a_exp + raw_b_exp                              ;
103	  assign prod_exp      = exp_sum - (BIASINT-(PADDINGBITS+1))                ;
104	  assign shift_lim_sub = {1'b0,exp_sum} - (BIASINT-PADDINGBITS)             ;
105	  assign prod_exp_uf   = shift_lim_sub[EXPWIDTH+1]                          ;
106	  assign shift_lim     = shift_lim_sub[EXPWIDTH:0]                          ;
107	  assign prod_exp_ov   = exp_sum > (MAXNORMEXP+BIASINT)                     ;
108	  assign subnormal_sig = a_exp_is_zero ? raw_a_sig : raw_b_sig              ;
109	  
110	  /*clz #(
111	    .LEN (PRECISION*2+2)
112	  )
113	  for_lzc (
114	    .in  ({{(PRECISION+2){1'd0}},subnormal_sig}),
115	    .out (lzc                                  )
116	  );*/
117	  wire lzc_zero; 
118	
119	  lzc #(
120	    .WIDTH     (PRECISION*2+2        ),
121	    .MODE      (1'b1                 ),
122	    .CNT_WIDTH ($clog2(PRECISION*2+2))
123	  )
124	  for_lzc (
125	    .in_i    ({{(PRECISION+2){1'd0}},subnormal_sig}),
126	    .cnt_o   (lzc                                  ),
127	    .empty_o (lzc_zero                             )
128	  );
129	
130	  assign exceed_lim    = shift_lim <= {{(EXPWIDTH-$clog2(PRECISION*2+2)){1'b0}},lzc};
131	  assign shift_amt     = prod_exp_uf ? 'd0 : (exceed_lim ? shift_lim : lzc)         ;
132	  assign exp_shifted   = prod_exp - shift_amt                                       ;
133	
134	  //outputs
135	  assign out_earyl_overflow_o   = prod_exp_ov               ;
136	  assign out_prod_sign_o        = prod_sign                 ;
137	  assign out_shift_amt_o        = shift_amt                 ;
138	  assign out_exp_shifted_o      = exp_shifted               ;
139	  assign out_may_be_subnormal_o = exceed_lim || prod_exp_uf ;
140	  assign out_rm_o               = rm_i                      ;
141	
142	  //special cases
143	  wire has_zero           ;
144	  wire has_nan            ;
145	  wire has_snan           ;
146	  wire has_inf            ;
147	  wire special_case_happen;
148	
149	  assign has_zero = a_is_zero || b_is_zero ;
150	  assign has_nan  = a_is_nan  || b_is_nan  ;
151	  assign has_snan = a_is_snan || b_is_snan ;
152	  assign has_inf  = a_is_inf  || b_is_inf  ;
153	  assign special_case_happen = has_zero || has_nan || has_inf ;
154	
155	  wire zero_mul_inf;
156	  wire nan_result  ;
157	  wire special_iv  ;
158	
159	  assign zero_mul_inf = has_zero && has_inf      ;
160	  assign nan_result   = has_nan  || zero_mul_inf ;
161	  assign special_iv    = has_snan || zero_mul_inf;
162	
163	  assign out_special_case_valid_o   = special_case_happen;
164	  assign out_special_case_nan_o     = nan_result         ;
165	  assign out_special_case_inf_o     = has_inf            ;
166	  assign out_special_case_inv_o     = special_iv         ;
167	  assign out_special_case_haszero_o = has_zero           ;
168	
169	endmodule
170	
171

